// Gold of Baku / Gold of Baku 2 — Spine FX layer (skeletons generated by
// scripts/gold_of_baku_fx.py into img/<game>/fx/). Pattern of
// js/ice-spin-deluxe/fx.js.
//
//   #fxBack  (under .stage)  — bg_desk / bg_mob, `idle` forever;
//   front stage (over the cabinet) — frame + logo (`idle`, `win` while a win
//            is on screen; the DOM logo is hidden once the Spine one is up),
//            winlines (fresh instance per shown payline), burst (small win),
//            shower (coin rain over the popup — the canvas is lifted above
//            #screenDim via body.fx-over-dim, base instances dimmed in Spine).
//
// Every instance is anchored to its DOM element, so CSS stays the only source
// of layout truth. If WebGL or an asset fails, BakuFx.ready stays false and
// slot.js keeps its CSS logo glow + SVG win line.

(function () {
  let root = '';
  let back = null;
  let front = null;
  const res = {};
  let bgInst = null;
  let bgVariant = null;
  let frameInst = null;
  let logoInst = null;
  let lineInst = null;
  let lineShown = 0;
  let burstInst = null;
  let burstTimer = null;
  let showerInst = null;
  let winOn = false;

  const BakuFx = { ready: false };

  function isMobile() {
    return window.matchMedia('(orientation: portrait)').matches;
  }

  function load(stage, name) {
    return SpineEngine.SpineResource.load(stage.assetManager, `${root}/${name}`, { premultipliedAlpha: true })
      .then((r) => { res[name] = r; return r; });
  }

  // The generator centres every skeleton on its authored box, and that box is
  // exactly the DOM element it is anchored to.
  function make(name, anchorEl) {
    const inst = res[name].createInstance();
    const sd = res[name].skeletonData;
    inst.anchorEl = anchorEl;
    inst.fit = 1;
    inst.boundsOverride = { x: sd.x, y: sd.y, width: sd.width, height: sd.height };
    return inst;
  }

  function mountBg() {
    const v = isMobile() ? 'bg_mob' : 'bg_desk';
    if (v === bgVariant || !res[v]) return;
    if (bgInst) back.removeBase(bgInst);
    bgVariant = v;
    bgInst = make(v, document.getElementById('stage'));
    bgInst.play('idle', true);
    back.addBase(bgInst);
  }

  // opts: { root, frontStage? } — gold-of-baku-2 passes its symbol stage (it
  // already sits over the cabinet), gold-of-baku gets its own #fxFront.
  BakuFx.load = function load_(opts) {
    root = opts.root;
    if (!window.spine || !window.SpineEngine) return Promise.resolve(false);
    try {
      back = new SpineEngine.SpineStage(document.getElementById('fxBack'));
      front = opts.frontStage || new SpineEngine.SpineStage(document.getElementById('fxFront'));
    } catch (err) {
      console.warn('[baku-fx] no WebGL — CSS fallback', err);
      return Promise.resolve(false);
    }
    return Promise.all([
      load(back, isMobile() ? 'bg_mob' : 'bg_desk'),
      load(front, 'frame'),
      load(front, 'logo'),
      load(front, 'winlines'),
      load(front, 'burst'),
      load(front, 'shower'),
    ]).then(() => {
      BakuFx.ready = true;
      mountBg();
      frameInst = make('frame', document.querySelector('.cabinet'));
      frameInst.play('idle', true);
      front.addBaseBehindAll(frameInst);
      logoInst = make('logo', document.querySelector('.logo'));
      logoInst.play('idle', true);
      front.addBase(logoInst);
      document.body.classList.add('fx-ready');
      load(back, isMobile() ? 'bg_desk' : 'bg_mob').catch(() => {});
      window.addEventListener('resize', () => {
        const v = isMobile() ? 'bg_mob' : 'bg_desk';
        if (res[v]) mountBg();
        else load(back, v).then(mountBg).catch(() => {});
      });
      return true;
    }).catch((err) => {
      console.warn('[baku-fx] assets failed — CSS fallback', err);
      return false;
    });
  };

  BakuFx.setWin = function setWin(on) {
    if (!BakuFx.ready || on === winOn) return;
    winOn = on;
    const clip = on ? 'win' : 'idle';
    frameInst.play(clip, true);
    logoInst.play(clip, true);
  };

  // Payline 1..5 (PAYLINE_ROWS index + 1). Re-showing the line already on
  // screen keeps its loop instead of restarting the draw-in.
  BakuFx.showLine = function showLine(n) {
    if (!BakuFx.ready) return false;
    if (n === lineShown && lineInst) return true;
    BakuFx.hideLine();
    lineInst = make('winlines', document.getElementById('reel'));
    lineInst.play(`line${n}_in`, false);
    lineInst.queue(`line${n}_loop`, true);
    lineShown = n;
    dimLine();
    front.addOverlay(lineInst);
    return true;
  };

  // Overlays aren't touched by setBaseDim; the win line is the one overlay
  // that can be on screen under a popup, so it is dimmed by hand.
  function dimLine() {
    if (!lineInst) return;
    const c = showerInst ? 0.25 : 1;
    lineInst.skeleton.color.set(c, c, c, 1);
  }

  BakuFx.hideLine = function hideLine() {
    if (lineInst) front.removeOverlay(lineInst);
    lineInst = null;
    lineShown = 0;
  };

  // Small win: star burst + coin fountain out of the reel window, once.
  BakuFx.burst = function burst() {
    if (!BakuFx.ready) return;
    if (burstInst) front.removeOverlay(burstInst);
    clearTimeout(burstTimer);
    const inst = make('burst', document.getElementById('reel'));
    inst.play('win', false);
    front.addOverlay(inst);
    burstInst = inst;
    // timer, not the complete event: a hidden tab ticks no frames
    burstTimer = setTimeout(() => {
      front.removeOverlay(inst);
      if (burstInst === inst) burstInst = null;
    }, 1700);
  };

  // Big/Mega/Epic popup: coin rain over the dim. The box is a 1000x1000
  // square; fitting it by the screen's longer side makes it cover the screen.
  BakuFx.startShower = function startShower() {
    if (!BakuFx.ready) return;
    BakuFx.stopShower();
    const screen = document.getElementById('screen');
    const inst = make('shower', screen);
    const wide = screen.clientWidth >= screen.clientHeight;
    inst.fitMode = wide ? 'width' : 'height';
    // portrait: the box still covers the narrow screen at 0.55, and the coins
    // come out phone-sized instead of saucers
    if (!wide) inst.fit = 0.55;
    inst.play('start', false);
    inst.queue('rain', true);
    showerInst = inst;
    front.addOverlay(inst);
    front.setBaseDim(true);
    dimLine();
    document.body.classList.add('fx-over-dim');
  };

  BakuFx.stopShower = function stopShower() {
    if (!showerInst) return;
    front.removeOverlay(showerInst);
    showerInst = null;
    front.setBaseDim(false);
    dimLine();
    document.body.classList.remove('fx-over-dim');
  };

  window.BakuFx = BakuFx;
})();
